BEGIN TRANSACTION;
CREATE TABLE iwisp_clients_cache (
                id TEXT PRIMARY KEY,
                client_id TEXT NOT NULL,
                client_name TEXT NOT NULL,
                onu_serial TEXT NOT NULL,
                onu_mac TEXT,
                onu_model TEXT,
                onu_brand TEXT,
                service_id TEXT,
                service_type TEXT,
                plan_id TEXT,
                plan_name TEXT,
                plan_cost TEXT,
                client_status TEXT,
                address TEXT,
                locality TEXT,
                zone TEXT,
                latitude REAL,
                longitude REAL,
                raw_data TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , consumed_tb REAL DEFAULT 0.0);
CREATE TABLE iwisp_directory (
            client_id TEXT PRIMARY KEY,
            client_name TEXT NOT NULL,
            normalized_name TEXT NOT NULL,
            rfc TEXT DEFAULT '',
            ine TEXT DEFAULT '',
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE links (
                id TEXT PRIMARY KEY,
                map_id TEXT NOT NULL,
                source_node_id TEXT NOT NULL,
                target_node_id TEXT NOT NULL,
                source_interface TEXT,
                target_interface TEXT,
                status TEXT DEFAULT 'ok',
                rtt_ms REAL DEFAULT 0.0,
                loss_percent REAL DEFAULT 0.0,
                extra_data TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, source_interface_id INTEGER, target_interface_id INTEGER, netbox_cable_id INTEGER, cable_type TEXT DEFAULT 'cat6', cable_status TEXT DEFAULT 'connected', zabbix_src_interface TEXT, zabbix_tgt_interface TEXT,
                FOREIGN KEY (map_id) REFERENCES maps(id) ON DELETE CASCADE,
                FOREIGN KEY (source_node_id) REFERENCES nodes(id) ON DELETE CASCADE,
                FOREIGN KEY (target_node_id) REFERENCES nodes(id) ON DELETE CASCADE
            );
CREATE TABLE map_hierarchy (
                id TEXT PRIMARY KEY,
                parent_map_id TEXT,
                child_map_id TEXT NOT NULL,
                alias TEXT,
                position INTEGER DEFAULT 0,
                is_primary BOOLEAN DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (child_map_id) REFERENCES maps(id) ON DELETE CASCADE,
                FOREIGN KEY (parent_map_id) REFERENCES maps(id) ON DELETE CASCADE
            );
CREATE TABLE maps (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                description TEXT,
                parent_map_id TEXT,
                grid_size INTEGER DEFAULT 20,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , position INTEGER DEFAULT 0, netbox_site_id INTEGER, site_name TEXT);
CREATE TABLE nodes (
                id TEXT PRIMARY KEY,
                map_id TEXT NOT NULL,
                device_id INTEGER,
                name TEXT NOT NULL,
                ip TEXT,
                device_type TEXT DEFAULT 'generic',
                site_name TEXT,
                x REAL NOT NULL DEFAULT 100.0,
                y REAL NOT NULL DEFAULT 100.0,
                status TEXT DEFAULT 'unknown',
                extra_data TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (map_id) REFERENCES maps(id) ON DELETE CASCADE
            );
CREATE TABLE olt_snmp_credentials (
                olt_ip TEXT PRIMARY KEY,
                community TEXT NOT NULL,
                vendor TEXT DEFAULT 'Huawei',
                notes TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE roles (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL UNIQUE,
                description TEXT,
                is_system BOOLEAN DEFAULT 0,
                permissions TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE system_config (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                description TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE user_roles (
                username TEXT PRIMARY KEY,
                role_id TEXT NOT NULL,
                custom_permissions TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE RESTRICT
            );
CREATE INDEX idx_iwisp_onu_serial ON iwisp_clients_cache(onu_serial);
CREATE INDEX idx_iwisp_client_id ON iwisp_clients_cache(client_id);
CREATE INDEX idx_iwisp_client_name ON iwisp_clients_cache(client_name);
CREATE INDEX idx_iwisp_service_id ON iwisp_clients_cache(service_id);
CREATE INDEX idx_iwisp_dir_norm ON iwisp_directory(normalized_name);
CREATE INDEX idx_maps_position ON maps(position);
CREATE INDEX idx_maps_netbox_site ON maps(netbox_site_id);
CREATE INDEX idx_maps_site_name ON maps(site_name);
CREATE INDEX idx_hierarchy_parent ON map_hierarchy(parent_map_id);
CREATE INDEX idx_hierarchy_child ON map_hierarchy(child_map_id);
CREATE INDEX idx_hierarchy_pos ON map_hierarchy(parent_map_id, position);
COMMIT;
